43	  leave(): void {
44	    if (this.phase !== 'flying') return;
45	    this.t?.send({ t: 'leave' });
46	    this.toWatching();
47	    this.onChange();
48	  }
49	
50	  sendPos(x: number, y: number, z: number, yaw: number, bank: number): void {
51	    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, bank });
52	  }
53	
54	  heartbeat(): void {
55	    if (this.phase === 'flying') this.t?.send({ t: 'hb' });
56	  }
57	
58	  dispose(): void {
