65	    this.flyers = this.flyers.filter(f => f.slot !== this.mySlotWas);
66	    this.fixWatched();
67	  }
68	  private mySlotWas = -1;
69	
70	  // Giữ watched nếu người đó còn; không thì chọn ngẫu nhiên người khác
71	  private fixWatched(): void {
72	    const ids = this.flyers.map(f => f.slot);
73	    if (this.phase === 'watching') {
74	      if (!ids.includes(this.watched)) this.watched = ids.length ? ids[this.pick(ids.length)] : -1;
75	      this.invite = ids.length < multiParams.slots;
76	    } else { this.watched = -1; this.invite = false; }
77	  }
78	
79	  private lost(): void {
80	    if (this.disposed) return;
81	    this.phase = 'solo'; this.notice = 'lost';
82	    this.flyers = []; this.mySlot = -1; this.watched = -1; this.invite = false;
83	    this.t = null; this.onChange();
84	  }
85	
86	  private recv(m: ServerMsg): void {
87	    if (this.disposed) return;
88	    switch (m.t) {
89	      case 'lobby':
90	        this.flyers = m.flyers;
91	        if (this.first) {
92	          this.first = false;
93	          if (m.flyers.length >= multiParams.slots) this.phase = 'watching';
94	          else this.phase = 'lobby';
95	        }
96	        // đang bay: danh sách chỉ để hiển thị
97	        this.fixWatched();
98	        break;
99	      case 'joined':
100	        this.phase = 'flying'; this.mySlot = m.slot; this.mySlotWas = m.slot; this.notice = '';
101	        this.fixWatched();
102	        break;
103	      case 'rejected':
104	        if (m.why === 'name') this.notice = 'nameBad';
105	        else {
106	          if (this.phase === 'watching') this.notice = 'late';
107	          else { this.phase = 'watching'; }
108	          this.fixWatched();
109	        }
110	        break;
111	      case 'pos':
112	        this.onPos(m.f);
113	        return;
114	      case 'released':
115	        if (this.phase === 'flying') { this.notice = 'released'; this.toWatching(); }
116	        break;
117	    }
118	    this.onChange();
119	  }
120	}
