1	// Kiểm tra dù lượn nhiều người ở phía khách (kế hoạch feature/du-luon-nhieu-nguoi, Task 5).
2	//   Mục 1: 4 bot Node WebSocket bay cùng — dù, màu, nhãn tên, nhãn dưới cánh, draw call (≤ +4), roster, bot thoát.
3	//   Mục 2: ?test không có multi= thì không mở WebSocket nào.
4	//   Mục 3 (Task 6): bước chọn slot + nhập tên trong màn chọn — số chỗ trực tiếp, tên, chống chèn HTML/RTL, nhớ tên, máy chủ tắt, đổi ngôn ngữ.
5	//   Mục 4 (Task 7): chế độ xem (5 bot), lời mời vào chỗ trống, giành trước, người xem rời, ô tên không lái dù, Esc, mất máy chủ khi xem và khi bay.
6	//   Tự spawn `wrangler dev` ở cổng 8799 và luôn kill khi xong hoặc lỗi.
7	//
8	//   npm run build && npm run test:multi
9	import { fileURLToPath } from 'node:url';
10	import { spawn } from 'node:child_process';
11	import { serveDir, launch, openApp, frames } from './lib.mjs';
12	
13	const PORT = 8799, HOST = `127.0.0.1:${PORT}`;
14	const problems = [];
15	const check = (name, ok) => { if (!ok) problems.push(name); console.log(`${ok ? 'đạt ' : 'LỖI '} ${name}`); return ok; };
16	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
17	
18	const wr = spawn(process.platform === 'win32' ? 'npx.cmd' : 'npx', ['wrangler', 'dev', '--port', String(PORT)], { cwd: fileURLToPath(new URL('../server/multi/', import.meta.url)), shell: process.platform === 'win32', stdio: ['ignore', 'pipe', 'pipe'] });
19	let log = ''; wr.stdout.on('data', (d) => { log += d; }); wr.stderr.on('data', (d) => { log += d; });
20	const stop = () => { try { if (process.platform === 'win32') spawn('taskkill', ['/pid', String(wr.pid), '/T', '/F']); else wr.kill(); } catch { /* bỏ qua */ } };
21	process.on('exit', stop);
22	
23	// Dù chính đứng yên ở BASE, hướng +X; bot bay tại chỗ phía trước, hơi lệch hai bên
24	const BASE = { x: 500, y: 150, z: 100 };
25	function bot(name, ox, oz) {
26	  const ws = new WebSocket(`ws://${HOST}/sky`, { headers: { Origin: 'http://127.0.0.1' } });
27	  const b = { ws, timer: null };
28	  ws.onopen = () => ws.send(JSON.stringify({ t: 'join', name }));
29	  ws.onmessage = (e) => {
30	    if (JSON.parse(e.data).t === 'joined' && !b.timer) b.timer = setInterval(() => ws.send(JSON.stringify({ t: 'pos', x: BASE.x + ox, y: BASE.y + 5, z: BASE.z + oz, yaw: 0, bank: 0 })), 200);
31	  };
32	  b.close = () => { clearInterval(b.timer); try { ws.close(); } catch { /* bỏ qua */ } };
33	  return b;
34	}
35	
36	let srv, browser, page;
37	const bots = [];
38	try {
39	  for (let i = 0; i < 120; i++) { if (/Ready on/.test(log)) break; await sleep(500); }
40	  check('wrangler dev sẵn sàng', /Ready on/.test(log));
41	  srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url)));
42	  browser = await launch();
43	
44	  // Mục 2 — không multi=: không mở WebSocket (cả ?explore=glider lẫn ?test thường)
45	  for (const q of ['', '?explore=glider']) {
46	    const P = await openApp(browser, srv.url + q);
47	    let ws = 0; P.page.on('websocket', () => ws++);
