46	    const P = await openApp(browser, srv.url + q);
47	    let ws = 0; P.page.on('websocket', () => ws++);
48	    await frames(P.page, 15);
49	    const u = await P.page.evaluate(() => window.__app.multi.url());
50	    check(`Không có multi= (${q || '?test'}): không có WebSocket nào được mở`, ws === 0 && u === '' && await P.page.evaluate(() => window.__app.multi.session) === null);
51	    await P.page.close();
52	  }
53	
54	  // Mục 3 — bước chọn slot và nhập tên (bắt đầu từ phòng trống; mọi bot/trang đóng trước Mục 1)
55	  {
56	    const URL3 = srv.url + '?chooser&multi=' + encodeURIComponent(`ws://${HOST}/sky`);
57	    const lobbyBots = [bot('Linh', 90, 0), bot('<img src>', 110, 18), bot('Sakura', 130, -18)];
58	    await sleep(2500);
