109	    check('Lỗi console của trang sảnh = 0', L.errors.length === 0);
110	    if (L.errors.length) console.log(L.errors.join('\n'));
111	    await L.page.close();
112	    lobbyBots.forEach((b) => b.close());
113	
114	    // Máy chủ tắt: cổng không có gì
115	    const O = await openApp(browser, srv.url + '?chooser&multi=' + encodeURIComponent('ws://127.0.0.1:9/sky'));
116	    await O.page.waitForSelector('#chooser', { state: 'visible', timeout: 240000 });
117	    await O.page.click('#chooser [data-pick="glider"]');
118	    await O.page.waitForFunction(() => !document.getElementById('exMpOffline').hidden, null, { timeout: 30000 }).catch(() => {});
119	    const off = await O.page.evaluate(() => ({ msg: document.getElementById('exMpOffline').innerText, solo: !document.getElementById('exMpSolo').hidden, name: document.getElementById('exMpNameIn').offsetParent !== null, fly: document.getElementById('exMpFly').offsetParent !== null }));
120	    check(`Máy chủ tắt: hiện "${off.msg}" và nút Bay một mình, không đòi tên`, off.msg.length > 0 && off.solo && !off.name && !off.fly);
